12	// Starts the app on a free port. call(method, path, body) sends one request; stop() closes the server.
13	export async function startApp(dataFile) {
14	  const server = createApp(dataFile)
15	  await new Promise((resolve, reject) => {
16	    server.once('error', reject)
17	    server.listen(0, '127.0.0.1', resolve)
18	  })
19	  const base = `http://127.0.0.1:${server.address().port}`
20	  return {
21	    call: (method, path, body) => request(base + path, method, body),
22	    stop: () => new Promise(resolve => server.close(resolve)),
23	  }
24	}
25	
26	// Runs fn with a running app on its own data file, then stops it and deletes the file.
27	export async function withApp(fn) {
28	  const data = tempDataFile()
29	  const app = await startApp(data.file)
30	  try {
31	    await fn(app.call)
32	  } finally {
33	    await app.stop()
34	    data.cleanup()
35	  }
36	}
